/* eslint-disable no-restricted-syntax, no-invalid-this, stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var EventEmitter = require( 'events' ).EventEmitter;
var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var instance2json = require( '@stdlib/plot/vega/base/to-json' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );
var defaults = require( './defaults.js' );

// Note: keep the following in alphabetical order according to the `require` path...
var getAs = require( './as/get.js' );
var setAs = require( './as/set.js' );

var getBandwidth = require( './bandwidth/get.js' );
var setBandwidth = require( './bandwidth/set.js' );

var getGroupby = require( './groupby/get.js' );
var setGroupby = require( './groupby/set.js' );

var getProperties = require( './properties/get.js' );

var getX = require( './x/get.js' );
var setX = require( './x/set.js' );

var getY = require( './y/get.js' );
var setY = require( './y/set.js' );


// VARIABLES //

var debug = logger( 'vega:loess-transform:main' );


// MAIN //

/**
* Loess transform constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {Field} options.x - data field for the independent variable (predictor)
* @param {Field} options.y - data field for the dependent variable (predicted)
* @param {NonNegativeNumber} [options.bandwidth=0.3] - bandwidth parameter
* @param {Array<Field>} [options.groupby] - data fields to group by
* @param {string} [options.as] - output field names for the predictor and predicted values for the line of best fit
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {LoessTransform} loess transform instance
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var transform = new LoessTransform({
*     'x': new Field({ 'field': 'dv' }),
*     'y': new Field({ 'field': 'iv' }),
*     'bandwidth': 0.2
* });
* // returns <LoessTransform>
*/
function LoessTransform( options ) {
	var self;
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof LoessTransform ) ) {
		return new LoessTransform( options );
	}
	self = this;
	EventEmitter.call( this );

	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}

	// Check for required properties...
	if ( !hasProp( options, 'x' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify a data field for the independent variable.' );
	}
	if ( !hasProp( options, 'y' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify a data field for the dependent variable.' );
	}

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
	}
	// Define an internal change event listener:
	this._onChange = onChange;

	// Add change listeners to default event emitters:
	if ( this._x && typeof this._x.on === 'function' ) {
		this._addChangeListener( this._x );
	}
	if ( this._y && typeof this._y.on === 'function' ) {
		this._addChangeListener( this._y );
	}

	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;

	/**
	* Callback invoked upon a change event.
	*
	* @private
	* @param {Object} event - event object
	*/
	function onChange( event ) {
		debug( 'Received a change event: %s', JSON.stringify( event ) );
		self.emit( 'change', event );
	}
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( LoessTransform, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof LoessTransform
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( LoessTransform, 'name', 'LoessTransform' );

/**
* Adds an internal listener to a change event on a child instance.
*
* @private
* @name _addChangeListener
* @memberof LoessTransform.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {LoessTransform} loess transform instance
*/
setNonEnumerableReadOnly( LoessTransform.prototype, '_addChangeListener', function addChangeListener( emitter ) {
	if ( emitter && typeof emitter.on === 'function' ) {
		emitter.on( 'change', this._onChange );
	}
	return this;
});

/**
* Adds internal listeners to change events on child instances.
*
* @private
* @name _addChangeListeners
* @memberof LoessTransform.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {LoessTransform} loess transform instance
*/
setNonEnumerableReadOnly( LoessTransform.prototype, '_addChangeListeners', function addChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._addChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* Removes an internal listener to a change event on a child instance.
*
* @private
* @name _removeChangeListener
* @memberof LoessTransform.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {LoessTransform} loess transform instance
*/
setNonEnumerableReadOnly( LoessTransform.prototype, '_removeChangeListener', function removeChangeListener( emitter ) {
	if ( emitter && typeof emitter.removeListener === 'function' ) {
		emitter.removeListener( 'change', this._onChange );
	}
	return this;
});

/**
* Removes internal listeners to change events on child instances.
*
* @private
* @name _removeChangeListeners
* @memberof LoessTransform.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {LoessTransform} loess transform instance
*/
setNonEnumerableReadOnly( LoessTransform.prototype, '_removeChangeListeners', function removeChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._removeChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* Output field names for the predictor and predicted values for the line of best fit.
*
* @name as
* @memberof LoessTransform.prototype
* @type {(string|void)}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var transform = new LoessTransform({
*     'x': new Field({ 'field': 'dv' }),
*     'y': new Field({ 'field': 'iv' }),
*     'as': 'predicted'
* });
*
* var v = transform.as;
* // returns 'predicted'
*/
setReadWriteAccessor( LoessTransform.prototype, 'as', getAs, setAs );

/**
* Bandwidth parameter.
*
* @name bandwidth
* @memberof LoessTransform.prototype
* @type {NonNegativeNumber}
* @default 0.3
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var transform = new LoessTransform({
*     'x': new Field({ 'field': 'dv' }),
*     'y': new Field({ 'field': 'iv' }),
*     'bandwidth': 0.2
* });
*
* var v = transform.bandwidth;
* // returns 0.2
*/
setReadWriteAccessor( LoessTransform.prototype, 'bandwidth', getBandwidth, setBandwidth );

/**
* Data fields to group by.
*
* @name groupby
* @memberof LoessTransform.prototype
* @type {(Array<Field>|void)}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var transform = new LoessTransform({
*     'x': new Field({ 'field': 'dv' }),
*     'y': new Field({ 'field': 'iv' }),
*     'groupby': [ new Field({ 'field': 'category' }) ]
* });
*
* var v = transform.groupby;
* // returns [...]
*/
setReadWriteAccessor( LoessTransform.prototype, 'groupby', getGroupby, setGroupby );

/**
* Loess transform properties.
*
* @name properties
* @memberof LoessTransform.prototype
* @type {Array<string>}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var transform = new LoessTransform({
*     'x': new Field({ 'field': 'dv' }),
*     'y': new Field({ 'field': 'iv' })
* });
*
* var v = transform.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( LoessTransform.prototype, 'properties', getProperties );

/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof LoessTransform.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var transform = new LoessTransform({
*     'x': new Field({ 'field': 'dv' }),
*     'y': new Field({ 'field': 'iv' }),
*     'bandwidth': 0.2
* });
*
* var v = transform.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( LoessTransform.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});

/**
* Data field for the independent variable (predictor).
*
* @name x
* @memberof LoessTransform.prototype
* @type {Field}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var transform = new LoessTransform({
*     'x': new Field({ 'field': 'dv' }),
*     'y': new Field({ 'field': 'iv' })
* });
*
* var v = transform.x;
* // returns <Field>
*/
setReadWriteAccessor( LoessTransform.prototype, 'x', getX, setX );

/**
* Data field for the dependent variable (predicted).
*
* @name y
* @memberof LoessTransform.prototype
* @type {Field}
*
* @example
* var Field = require( '@stdlib/plot/vega/field/ctor' );
*
* var transform = new LoessTransform({
*     'x': new Field({ 'field': 'dv' }),
*     'y': new Field({ 'field': 'iv' })
* });
*
* var v = transform.y;
* // returns <Field>
*/
setReadWriteAccessor( LoessTransform.prototype, 'y', getY, setY );


// EXPORTS //

module.exports = LoessTransform;
